    dedupe_key: str = Field(..., max_length=200, min_length=8)
    from_state: SignalState | None
    to_state: SignalState
    cause: str = Field(..., max_length=240)
    evidence_asof_at: UtcTimestamp | None = None
    payload: dict[str, Any]


